using namespace dome;
namespace {std::atomic_bool throttle=false;size_t checks=0;void check(bool b,const char*m){if(!b)throw std::runtime_error(m);++checks;std::cout<<"PASS "<<m<<std::endl;}bool same(const std::vector<Vec3>&a,const std::vector<Vec3>&b){return a.size()==b.size()&&std::equal(a.begin(),a.end(),b.begin(),[](auto x,auto y){return x.x==y.x&&x.y==y.y&&x.z==y.z;});}}
extern "C" bool real_stamp(ShapeSculptDraft*,const Brush&,const std::function<bool()>&) asm("__real__ZN4dome16ShapeSculptDraft5stampERKNS_5BrushERKSt8functionIFbvEE");
extern "C" bool wrap_stamp(ShapeSculptDraft*,const Brush&,const std::function<bool()>&) asm("__wrap__ZN4dome16ShapeSculptDraft5stampERKNS_5BrushERKSt8functionIFbvEE");
extern "C" bool wrap_stamp(ShapeSculptDraft*d,const Brush&b,const std::function<bool()>&c){auto due=std::chrono::steady_clock::now()+std::chrono::milliseconds(40);auto result=real_stamp(d,b,c);if(throttle)std::this_thread::sleep_until(due);return result;}
namespace {
void done(Document&d){if(!d.wait_native_stroke(std::chrono::seconds(120))||!d.wait_asset(std::chrono::seconds(120))||!d.wait_mesh(std::chrono::seconds(120))||!d.frame().state->error.empty())throw std::runtime_error("Derived stroke endpoint: "+d.frame().state->error);}
nlohmann::json paint(const PaintedMesh&p){PaintImageArchive images;NormalSamplingArchive normals;PaintSamplingArchive grids;auto j=p.encode(&images,&normals,&grids);j["normal_domains"]=normals.encode(images);j["paint_domains"]=grids.encode();j["images"]=images.encode();return j;}
void preview(Document&d,size_t n){auto end=std::chrono::steady_clock::now()+std::chrono::seconds(30);while(d.frame().state->native_samples<n&&d.frame().state->error.empty()&&std::chrono::steady_clock::now()<end)std::this_thread::yield();if(!d.frame().state->error.empty())throw std::runtime_error(d.frame().state->error);check(d.frame().state->native_samples>=n&&d.wait_mesh(std::chrono::seconds(30))&&d.frame().surface->native_samples>=n,"Real independent-key sample and its rendered mesh acknowledge the processed prefix");}
NativeStrokeSample ray(Document&d){const auto f=d.frame();const auto &mesh=f.surface->mesh;std::unique_ptr<MaterialSurfaceQuery> local;const auto*query=f.surface->picking.get();if(!query){local=std::make_unique<MaterialSurfaceQuery>(mesh,f.surface->ranges,std::function<bool()>{},f.surface->source_colors,PaintVertexCoordinates{f.surface->paint_coordinates});query=local.get();}check(bool(query),"Visible-ray fixture uses actual published material ranges and explicit packed coordinates");for(size_t c=0;c<mesh.indices.size();c+=3)for(size_t v=0;v<3;++v){Vec3 p{};for(size_t k=0;k<3;++k)p+=mesh.positions[mesh.indices[c+k]]*(k==v?.97f:.015f);NativeStrokeSample s;s.origin=p+Vec3{0,0,2};s.direction={0,0,-1};auto h=query->raycast(s.origin,s.direction,4);if(h&&length(h->position-p)<1e-4f){s.brush.radius=.3f;s.brush.tool=Tool::Clay;s.brush.strength=1;return s;}}throw std::runtime_error("No visible derived6 vertex for a real shape brush");}
struct Hand{Document&d;SpatialFrame f;explicit Hand(Document&v):d(v){f.focused=f.head_valid=true;f.head.position={0,1.6f,0};f.hands[1].tracked.valid=f.hands[1].tracked.aimValid=true;}void send(const NativeStrokeSample&s,float pressure){++f.sequence;f.time+=.05;auto&h=f.hands[1].tracked;h.aim.position=h.grip.position=ob::transform(d.frame().state->canvas,{s.origin.x,s.origin.y,s.origin.z});h.aim.orientation=h.grip.orientation=d.frame().state->canvas.orientation;h.trigger=pressure;d.submit(f);if(!d.wait_input())throw std::runtime_error("Real controller input did not drain");}};
void run(const Scene&source,bool controller,const std::filesystem::path&file,bool existing=false){Document d;d.replace(source);done(d);const auto count=existing?size_t(0):source.active().deformation->morphs->targets.size();if(!existing){ShapeKeyEdit key;key.name="Actual independent freehand";d.author_shape(key);done(d);}check(d.frame().state->morph_target==count,"Actual native source/new target selection addresses its real derived6 slot");d.configure_shape_sculpt(true);d.configure(Tool::Clay,.3f);done(d);const auto before=d.copy_scene();const auto exact=before.encode();const auto binding=before.active().material_bindings;const auto geometry=before.active().painted->mesh_owner();const auto paint_before=paint(*before.active().painted);auto sample=ray(d);Hand hand(d);throttle=true;if(controller)hand.send(sample,0);else check(d.begin_native_stroke(),"Desktop independent-key gesture is admitted");
 for(size_t n=0;n<3;++n){sample.brush.pressure=.4f+.2f*float(n);if(controller)hand.send(sample,sample.brush.pressure);else check(d.sample_native_stroke(sample),"Real ordered desktop target sample is accepted");preview(d,n+1);check(d.copy_scene().encode()==exact,"Every visible changed target preview leaves authoritative data/history untouched");}
 if(controller)hand.send(sample,0);else d.end_native_stroke(true);auto saved=d.save_async(file);saved.get();done(d);const auto after=d.copy_scene();check(!same(after.active().deformation->morphs->targets[count].delta,before.active().deformation->morphs->targets[count].delta),"Actual desktop/controller freehand changes independent target positions");if(existing){const auto&a=after.active().deformation->morphs->targets[0].delta[0],&b=after.active().deformation->morphs->targets[0].delta[3];check(a.x!=b.x||a.y!=b.y||a.z!=b.z,"Real freehand preserves contradictory source-vertex seam endpoints instead of averaging them");const auto old_a=before.active().deformation->morphs->targets[0].delta[0],old_b=before.active().deformation->morphs->targets[0].delta[3];const auto da=a-old_a,db=b-old_b;check(da.x!=db.x||da.y!=db.y||da.z!=db.z,"Actual brush falloff independently changes the two seam copies with no source-vertex contraction");}check(after.active().painted->mesh_owner()==geometry&&paint(*after.active().painted)==paint_before&&after.active().shape_source==before.active().shape_source&&after.active().rig_source==before.active().rig_source&&after.active().material_bindings->key_derivation->before_material()==binding->key_derivation->before_material(),"Repeated actual shape previews preserve exact paint/detail/rig/original source and one fixed key anchor");
 check(after.active().deformation->morph_weights==before.active().deformation->morph_weights&&Scene::load(file).encode()==after.encode(),"Actual ordered Save/restart preserves source weights and the complete freehand endpoint");check(d.undo()&&d.copy_scene().encode()==exact&&d.redo()&&d.copy_scene().encode()==after.encode(),"Whole independent-key gesture has one exact global Undo/Redo");done(d);
 const auto accepted=after.encode();if(controller)hand.send(sample,0);else check(d.begin_native_stroke(),"Cancelled independent target gesture is admitted");for(size_t n=0;n<2;++n){if(controller)hand.send(sample,.8f);else check(d.sample_native_stroke(sample),"Changed cancellation prefix is accepted");preview(d,n+1);}if(controller){hand.f.focused=false;hand.send(sample,.8f);}else d.end_native_stroke(false);done(d);check(d.copy_scene().encode()==accepted,"Real changed-preview Cancel/controller focus loss preserves the exact accepted scene");throttle=false;
}
}
int main(int argc,char**argv)try{if(argc!=3)return 2;std::filesystem::path out=argv[2];std::filesystem::create_directories(out);auto scene=Scene::load(argv[1]);check(scene.active().painted->mesh().positions.size()==6&&scene.active().material_bindings->normal_frames->position_domain,"Input is the actual saved owning derived6 key model");run(scene,false,out/"desktop.dsculpt");run(scene,true,out/"controller.dsculpt");run(scene,false,out/"desktop-existing-seam.dsculpt",true);run(scene,true,out/"controller-existing-seam.dsculpt",true);std::cout<<"PASS "<<checks<<" derived native/controller stroke checks"<<std::endl;return 0;}catch(const std::exception&e){throttle=false;std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}
